def render(req):
    out = ['## 11. Service specifications', '', 'One subsection per service the graphs depend on. Each gives the purpose, interface, inputs, behaviour, outputs and errors, what it records, and its status. **SVC-01** is specified from the code as it runs today, with target behaviour marked; the others are target design.', '',
           '| ID | Service | Component | Status |', '|---|---|---|---|']
    for s in SERVICES:
        out.append(f"| {s['id']} | {s['name']} | {s['component']} | {s['status']} |")
    out.append('')
    for s in SERVICES:
        out += [f"### 11.{SERVICES.index(s) + 1} {s['id']} {s['name']} ({s['component']})", '', f"**Purpose.** {s['purpose']}", '', f"**Status.** {s['status']}", '',
                '**Interface**', '', '| | |', '|---|---|'] + [f"| {a} | {b} |" for a, b in s['interface']] + ['']
        out += ['**Inputs**', '', '| Input | Detail |', '|---|---|'] + [f"| {a} | {b} |" for a, b in s['inputs']] + ['']
        out += ['**Behaviour**', '', '| Step | Does | On failure / settings / limits |', '|---|---|---|'] + [f"| {a} | {b} | {c} |" for a, b, c in s['steps']] + ['']
        out += [f"**Validity.** {s['valid']}", '', '**Target design**', '', '| | |', '|---|---|'] + [f"| {a} | {b} |" for a, b in s['target']] + ['']
        out += ['**Records**', '', '| Field | Content |', '|---|---|'] + [f"| {a} | {b} |" for a, b in s['records']] + ['']
        req('S', f"{s['id']} {s['name']}: implement to §11.{SERVICES.index(s) + 1}.", s['component'], s['status'].split(' (')[0].split(' —')[0])
    return out
